from pathlib import Path
import json
root=Path(__file__).resolve().parent.parent
data=(root/'viewer_data.json').read_text().replace('</','<\\/')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>OspC panel comparison v0.1.0</title><style>
:root{font:15px system-ui;color:#18323b;background:#f4f7f8}body{max-width:1250px;margin:24px auto;padding:0 18px}h1{font-size:27px}h2{font-size:19px}section{background:white;padding:18px;margin:16px 0;border:1px solid #dce5e8;border-radius:8px}p{line-height:1.5}label,button,input{font:inherit}button,input{padding:5px}a{color:#075c82}.badges{display:flex;gap:12px;flex-wrap:wrap}.badges div{padding:12px;background:#e9f2f4;border-radius:5px}.badges strong{font-size:23px;display:block}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}@media(max-width:750px){.grid{grid-template-columns:1fr}}canvas{display:block;max-width:100%;border:1px solid #dce5e8;background:#fff}#plot{cursor:crosshair;width:100%;height:200px}#trace{width:100%;height:360px;touch-action:none;cursor:grab}.scroll{overflow:auto;max-height:650px}table{border-collapse:collapse}td,th{padding:5px;text-align:left;border-bottom:1px solid #eee;white-space:nowrap}#alignment{font:13px monospace}#alignment td,#alignment th{padding:0;width:13px;min-width:13px;text-align:center;height:20px}#alignment th:first-child{position:sticky;left:0;background:white;z-index:2;text-align:left;width:145px;min-width:145px;padding:0 6px}#alignment thead th{position:sticky;top:0;background:#e5edf0;z-index:3}#alignment thead th:first-child{z-index:4}#alignment .selected{outline:2px solid #143a86;outline-offset:-2px}#detail{white-space:pre-wrap;font:14px monospace;line-height:1.6}small{color:#46616d}code{overflow-wrap:anywhere}summary{cursor:pointer}#metadata{font-size:12px}#metadata td{white-space:normal;vertical-align:top}#metadata{width:100%}#unscored{font-size:13px}</style></head><body>
<h1>OspC comparison · analyzed panel v0.1.0</h1><p>Actual MAFFT alignment of the frozen natural-sequence panel. Descriptive conservation <strong>within this analyzed panel</strong>; no protection or antigen-safety inference.</p>
<div class="badges" id="badges"></div>
<section><h2>Conservation and coverage</h2><p>Orange: modal amino-acid fraction among standard residues. Blue: standard-residue coverage out of 30 sequences. These quantities have different denominators. Click the plot or select a column to inspect both.</p><canvas id="plot" width="1150" height="200" aria-label="Conservation and coverage by alignment column"></canvas><p><button id="prev">← Previous</button> <label>Alignment column <input id="column" type="number" min="1" max="218" value="1" style="width:75px"></label> <button id="next">Next →</button></p><div id="detail"></div></section>
<section><h2>Alignment</h2><p>Cells use the column's orange conservation shade; gaps are gray. Click any cell. Hover an accession for its supplied organism and strain. Identifiers and ungapped sequences were verified unchanged.</p><div class="scroll" id="alignmentScroll"><table id="alignment"></table></div></section>
<section class="grid"><div><h2>Pre-existing experimental reference</h2><p><strong>1GGQ chain A, model 1</strong>. This is a rotatable Cα trace of experimental coordinates, not generated folding or a molecular surface. Orange colors use the mapped panel conservation. Drag to rotate; click a residue to select its alignment column. Selected residue is blue. B-factors are not confidence scores.</p><canvas id="trace" width="560" height="360"></canvas><small>173 native construct residues verified; 162 observed Cα positions scored. Missing coordinates cannot appear in the trace. The extra initiating methionine is unmapped.</small></div><div><h2>Unscored reference positions</h2><p>Unobserved or unmapped positions remain unscored. Conservation in the alignment is distinct from whether experimental coordinates exist.</p><div class="scroll" style="max-height:380px"><table id="unscored"><thead><tr><th>Author residue</th><th>AA</th><th>Panel position</th><th>Status</th></tr></thead><tbody></tbody></table></div><p><a href="alignment_to_structure.tsv">Column-to-residue mapping TSV</a> · <a href="structure_residues.tsv">All construct residues TSV</a></p></div></section>
<section><h2>Scope and limitations</h2><p id="scope"></p><p>Alignment: MAFFT L-INS-i, amino acid, one thread, 1,000 maximum refinement iterations. Conservation is unweighted modal residue count divided by observed standard amino acids. Ties retain all modes and display the alphabetical first. A column with no standard observations is undefined. Low coverage can yield a fraction of 1 from few observations; inspect coverage alongside it. Alignment uncertainty, evolutionary relatedness, isolate sampling and biological accessibility are not modeled.</p><details><summary>All supplied accession / organism / strain metadata</summary><table id="metadata"><thead><tr><th>Accession</th><th>Organism</th><th>Primary strain</th><th>Flags</th></tr></thead><tbody></tbody></table></details><p><a href="aligned.fasta">Aligned FASTA</a> · <a href="conservation_coverage.tsv">Conservation/coverage TSV</a> · <a href="viewer_data.json">Viewer JSON</a> · <a href="METHOD_AND_LIMITATIONS.md">Methods and hashes</a> · <a href="secondary_reference_check.json">1G5Z check</a></p><small>Offline view: data are embedded; no CDN, network request, public server or model is required.</small></section>
<script id="data" type="application/json">__DATA__</script><script>
'use strict';const D=JSON.parse(document.getElementById('data').textContent),N=D.columns.length,$=s=>document.querySelector(s);let chosen=1,rx=.3,ry=.6,drag=null,projected=[];const pct=x=>x===null?'undefined':(100*x).toFixed(1)+'%',tone=x=>x===null?'#b6bdc1':`rgb(255,${Math.round(248-130*x)},${Math.round(225-190*x)})`;
function txt(tag,text,parent){let e=document.createElement(tag);e.textContent=text;parent.append(e);return e}
for(const [n,label]of [[30,'sequences'],[N,'alignment columns'],[D.summary.fully_covered_identical_columns,'identical at full coverage'],[162,'observed reference residues scored']]){let e=txt('div','',$('#badges'));txt('strong',n,e);txt('span',label,e)}
$('#scope').textContent=`${D.scope.sequences} accessions; ${D.scope.distinct_nonblank_strain_labels} distinct nonblank strain labels; ${D.scope.blank_strain_fields} unresolved/missing strain fields. Strain-label count is not a count of distinct biological strains. ${Object.keys(D.scope.organism_labels).length} supplied organism labels are preserved. This is a sequence-distinct convenience panel, not universally representative.`;
let table=$('#alignment'),head=table.createTHead().insertRow();txt('th','Accession / column',head);for(let c=1;c<=N;c++)txt('th',c%10===0?c:'·',head);let body=table.createTBody();
for(const s of D.sequences){let tr=body.insertRow(),label=txt('th',s.accession,tr);label.title=s.metadata.organism+' | strain: '+(s.metadata.strain||'unresolved/missing');for(let i=0;i<N;i++){let cell=txt('td',s.aligned_sequence[i],tr);cell.dataset.col=i+1;cell.style.background=s.aligned_sequence[i]==='-'?'#e2e5e7':tone(D.columns[i].modal_fraction);cell.title=`Column ${i+1}; fraction ${pct(D.columns[i].modal_fraction)}; coverage ${pct(D.columns[i].coverage)}`}}
table.addEventListener('click',e=>{let c=e.target.dataset.col;if(c)select(+c)});
for(const s of D.sequences){let tr=$('#metadata tbody').insertRow();for(const x of [s.accession,s.metadata.organism,s.metadata.strain||'unresolved/missing',s.metadata.quality_flags])txt('td',x,tr)}
for(const r of D.structure_residues.filter(r=>!r.has_observed_CA||r.panel_sequence_position===null)){let tr=$('#unscored tbody').insertRow();for(const x of [r.auth_residue_number+r.insertion_code,r.aa,r.panel_sequence_position??'unmapped',r.mapping_status])txt('td',x,tr)}
function plot(){let cv=$('#plot'),g=cv.getContext('2d'),w=cv.width,h=cv.height,left=46,right=w-10,cw=(right-left)/N;g.clearRect(0,0,w,h);g.font='12px system-ui';for(const [base,color,key,label]of [[85,'#d87d26','modal_fraction','Modal fraction'],[165,'#137f9b','coverage','Coverage']]){g.fillStyle='#304954';g.fillText(label,left,base-62);g.fillText('1',25,base-48);g.fillText('0',25,base);g.strokeStyle='#d6dfe3';g.beginPath();g.moveTo(left,base);g.lineTo(right,base);g.stroke();for(let i=0;i<N;i++){let value=D.columns[i][key];if(value!==null){g.fillStyle=color;g.fillRect(left+i*cw,base-50*value,Math.max(.5,cw-.5),50*value)}}}g.strokeStyle='#183b85';let x=left+(chosen-.5)*cw;g.beginPath();g.moveTo(x,8);g.lineTo(x,170);g.stroke();g.fillStyle='#304954';for(let c of [1,50,100,150,200,N])g.fillText(c,left+(c-.5)*cw-4,190)}
$('#plot').addEventListener('click',e=>{let b=e.target.getBoundingClientRect(),x=(e.clientX-b.left)*e.target.width/b.width;select(Math.floor((x-46)/(e.target.width-56)*N)+1)});
function trace(){let cv=$('#trace'),g=cv.getContext('2d'),w=cv.width,h=cv.height,rs=D.structure_residues.filter(r=>r.xyz);g.clearRect(0,0,w,h);let mean=[0,0,0];for(let r of rs)r.xyz.forEach((v,i)=>mean[i]+=v/rs.length);projected=rs.map(r=>{let[x,y,z]=r.xyz.map((v,i)=>v-mean[i]),xx=x*Math.cos(ry)+z*Math.sin(ry),zz=-x*Math.sin(ry)+z*Math.cos(ry),yy=y*Math.cos(rx)-zz*Math.sin(rx);return {r,x:w/2+xx*5,y:h/2+yy*5}});for(let i=1;i<projected.length;i++){let a=projected[i-1],b=projected[i];if(b.r.label_seq_id-a.r.label_seq_id!==1)continue;g.strokeStyle=tone(b.r.modal_fraction);g.lineWidth=5;g.beginPath();g.moveTo(a.x,a.y);g.lineTo(b.x,b.y);g.stroke()}for(let p of projected){g.fillStyle=p.r.alignment_column===chosen?'#173e9a':tone(p.r.modal_fraction);g.beginPath();g.arc(p.x,p.y,p.r.alignment_column===chosen?6:2,0,2*Math.PI);g.fill()}g.fillStyle='#304954';g.font='12px system-ui';g.fillText('1GGQ A · experimental Cα trace · drag to rotate',12,20)}
$('#trace').addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,moved:false};e.target.setPointerCapture(e.pointerId)});$('#trace').addEventListener('pointermove',e=>{if(!drag)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>1)drag.moved=true;ry+=dx*.01;rx+=dy*.01;drag.x=e.clientX;drag.y=e.clientY;trace()});$('#trace').addEventListener('pointerup',e=>{if(drag&&!drag.moved){let b=e.target.getBoundingClientRect(),x=(e.clientX-b.left)*e.target.width/b.width,y=(e.clientY-b.top)*e.target.height/b.height,nearest=projected.reduce((a,p)=>Math.hypot(p.x-x,p.y-y)<Math.hypot(a.x-x,a.y-y)?p:a);if(Math.hypot(nearest.x-x,nearest.y-y)<20)select(nearest.r.alignment_column)}drag=null});
function select(c){chosen=Math.max(1,Math.min(N,Math.round(c)||1));$('#column').value=chosen;let s=D.columns[chosen-1],m=D.mapping[chosen-1];$('#detail').textContent=`Column ${chosen} | mode ${s.most_frequent_aa??'undefined'} | tied modes ${s.tied_modes||'none'}\nModal fraction ${pct(s.modal_fraction)} | coverage ${pct(s.coverage)} (${s.contributing_sequences}/30)\nGaps ${s.gap_count} | ambiguous/missing ${s.ambiguous_missing_count}\nQ07337 position ${m.panel_sequence_position??'gap'} (${m.reference_aa}) → 1GGQ A author residue ${m.auth_residue_number??'unmapped'}${m.insertion_code??''}\nMapping status: ${m.status} | structure score: ${m.structure_modal_fraction===null?'unscored':pct(m.structure_modal_fraction)}`;for(let cell of document.querySelectorAll('#alignment td.selected'))cell.classList.remove('selected');for(let cell of document.querySelectorAll(`#alignment td[data-col="${chosen}"]`))cell.classList.add('selected');let sc=$('#alignmentScroll');sc.scrollLeft=Math.max(0,145+(chosen-1)*13-sc.clientWidth/2);plot();trace()}
$('#column').addEventListener('change',e=>select(+e.target.value));$('#prev').addEventListener('click',()=>select(chosen-1));$('#next').addEventListener('click',()=>select(chosen+1));select(1);
</script></body></html>'''
(root/'index.html').write_text(page.replace('__DATA__',data))
print(root/'index.html')
